package com.acme.realestate.listings;

import java.math.BigDecimal;

/**
 * Validates that a listing has all mandatory fields before publication.
 */
public class ListingPublicationGuard {

    public void assertPublishable(ListingDraft draft) {
        if (draft.getAskingPrice() == null || draft.getAskingPrice().signum() <= 0) {
            throw new ValidationException("Asking price is required and must be positive");
        }
        if (draft.getAddress() == null || draft.getAddress().isBlank()) {
            throw new ValidationException("Address is required");
        }
        if (draft.getPropertyType() == null) {
            throw new ValidationException("Property type is required");
        }
    }
}

class ValidationException extends RuntimeException {
    public ValidationException(String message) { super(message); }
}

