package com.acme.realestate.valuation;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Estimates a monthly mortgage repayment for a listing.
 */
public class MortgageEstimateCalculator {

    private final BigDecimal annualInterestRate;
    private final int termYears;

    public MortgageEstimateCalculator(BigDecimal annualInterestRate, int termYears) {
        this.annualInterestRate = annualInterestRate;
        this.termYears = termYears;
    }

    public BigDecimal monthlyRepayment(BigDecimal askingPrice, BigDecimal deposit) {
        BigDecimal principal = askingPrice.subtract(deposit);
        if (principal.signum() <= 0) {
            return BigDecimal.ZERO;
        }
        double r = annualInterestRate.doubleValue() / 100.0 / 12.0;
        int n = termYears * 12;
        double payment = principal.doubleValue() * r / (1 - Math.pow(1 + r, -n));
        return BigDecimal.valueOf(payment).setScale(2, RoundingMode.HALF_UP);
    }
}

