package com.acme.realestate.search;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Listing search endpoint by location and price band, newest first.
 */
@RestController
public class ListingSearchController {

    private final ListingSearchDao dao;

    public ListingSearchController(ListingSearchDao dao) {
        this.dao = dao;
    }

    @GetMapping("/listings/search")
    public List<ListingSummary> search(@RequestParam String location,
                                       @RequestParam BigDecimal minPrice,
                                       @RequestParam BigDecimal maxPrice,
                                       @RequestParam(defaultValue = "0") int page,
                                       @RequestParam(defaultValue = "20") int size) {
        if (minPrice.compareTo(maxPrice) > 0) {
            throw new IllegalArgumentException("Minimum price exceeds maximum");
        }
        return dao.findPublished(location, minPrice, maxPrice, page, size).stream()
            .map(ListingSummary::from)
            .toList();
    }
}

