package com.acme.realestate.viewings;

import java.time.Instant;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Viewing request endpoint: check agent availability, record request.
 */
@RestController
public class ViewingRequestController {

    private final AgentAvailabilityService availability;
    private final ViewingRequestRepository requests;
    private final NotificationGateway notifier;

    public ViewingRequestController(AgentAvailabilityService availability, ViewingRequestRepository requests, NotificationGateway notifier) {
        this.availability = availability;
        this.requests = requests;
        this.notifier = notifier;
    }

    @PostMapping("/viewings")
    public ViewingView request(@RequestBody ViewingRequest req) {
        if (!availability.isFree(req.getAgentId(), req.getRequestedAt())) {
            throw new SlotUnavailableException(req.getAgentId(), req.getRequestedAt());
        }
        ViewingRequest saved = requests.save(new ViewingRequest(req.getListingId(), req.getBuyerId(), req.getAgentId(), req.getRequestedAt()));
        notifier.send(req.getAgentId(), "New viewing request for listing " + req.getListingId());
        return ViewingView.from(saved);
    }
}

