/**
 * Marks a listing as under offer and pauses new viewings.
 */
public class UnderOfferService {

    private final ListingRepository listings;
    private final ViewingRequestRepository viewings;

    public UnderOfferService(ListingRepository listings, ViewingRequestRepository viewings) {
        this.listings = listings;
        this.viewings = viewings;
    }

    public void markUnderOffer(String listingId, String sellerId) {
        Listing l = listings.require(listingId);
        if (!l.getSellerId().equals(sellerId)) {
            throw new IllegalStateException("Not your listing");
        }
        l.setStatus(ListingStatus.UNDER_OFFER);
        l.setUnderOfferAt(Instant.now());
        listings.save(l);
        viewings.pauseNewForListing(listingId);
    }
}

