package com.acme.realestate.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row on each listing price or status change.
 */
public class ListingChangeAuditor {

    private final EntityManager em;

    public ListingChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String listingId, String field, String oldValue, String newValue, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ListingChangeEntry e = new ListingChangeEntry();
            e.setListingId(listingId);
            e.setField(field);
            e.setOldValue(oldValue);
            e.setNewValue(newValue);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

