/* stale_listings_report.c - write stale listings report */
#include <stdio.h>
#include "realestate_db.h"

int write_stale_listings(const char *today, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "listing_id,agent_id,days_listed,enquiries\n");

    db_cursor_t *cur = NULL;
    if (db_open_stale_listings_cursor(&cur, today, 30, 5) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    stale_row_t row;
    while (db_stale_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%s,%d,%d\n",
                row.listing_id, row.agent_id, row.days_listed, row.enquiries);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

